public abstract class LayerObject {
    private readonly long _id;
    protected LayerObject(long id) => _id = id;     // shared state
    public long Id => _id;
    public void Touch() => Version++;               // shared implementation
    protected int Version { get; private set; }
    public abstract string Describe();              // required per member
}
public sealed class User : LayerObject {
    public User(long id) : base(id) { }
    public override string Describe() => $"user {Id}";
}
